window.__EMBEDDED_DATA__ = {
  riskTypes: {"version": "3.0", "lastUpdated": "2026-09-01", "author": "羽织梦", "motto": "以梦化羽；所织皆梦，所梦皆羽", "copyright": "© 2026 羽织梦 版权所有", "note": "风险清单基于《OPC企业风险故事线与风险链（完整版）》整理：2 大风险域、8 个风险类、24 项具体风险。治理策略与智能体逻辑与《第五章 人工智能OPC特有风险智能治理智能体设计与应用》保持一致。", "categories": [{"id": "internal", "name": "内源主体脆弱性风险", "description": "源于创业者自身能力、健康、认知、资源与社会支持的风险", "color": "#5B8FF9", "icon": "🧭"}, {"id": "external", "name": "外源环境与技术协同风险", "description": "源于 AI 技术、平台生态与制度环境的协同风险", "color": "#F6BD16", "icon": "🌐"}], "risks": [{"id": "1.1", "name": "多维能力瓶颈风险", "shortName": "能力瓶颈", "categoryId": "internal", "categoryName": "内源主体脆弱性风险", "characterImage": "character_1_1.jpg", "characterImagePlaceholder": "🧭", "color": "#5B8FF9", "level": "high", "description": "创业者在技术能力、AI 协同、管理商业化、法律财税等多维度存在能力短板，且业务高度非标、难以复制，难以支撑业务持续发展。", "specificRisks": [{"id": "1.1.1", "name": "技术能力不足", "quote": "我自己对 AI 的了解还比较浅，要提升的东西太多了", "source": "SoloNest 徐超越"}, {"id": "1.1.2", "name": "AI 协同能力滞后", "quote": "我是从一个非常抗拒 AI 的人，到现在可以跟它非常自洽地相处……一开始聊着聊着会生气，因为它很能说但又说不到点上，你不知道怎么跟它沟通。", "source": "SoloNest 宁宁"}, {"id": "1.1.3", "name": "管理与商业化能力缺失", "quote": "做了之后怎么让客户知道这个东西、怎么让他们去用？这是最痛的痛点。我也尝试去地推过，推了三家只有一家有一点意愿把我微信加上了", "source": "OPC 邢恩"}, {"id": "1.1.4", "name": "法律财税知识空白", "quote": "防止法人的面纱穿透的东西，我觉得是需要科普，我最近专门做了一期活动，找了一个律师过来专门讲了一期内容，怎么防止法人的面纱穿透", "source": "SoloNest Karen"}, {"id": "1.1.5", "name": "非标化规模壁垒", "quote": "我现在的业务，它就绑在我自己身上，比较难规模化，它很难复制……因为标准化的大规模的一定有大厂早就已经做了，一人公司的机会点就是非标的，然后很小的利基市场", "source": "SoloNest Karen"}], "symptoms": ["工具使用停留在表层，无法深度协同", "产品做出来了但不会推广获客", "法律财税问题只能事后补救", "业务绑定个人、难以标准化复制"], "causes": ["持续学习投入不足", "对 AI 工具能力边界认知不清", "知识结构单一，缺乏跨领域积累", "一人承担多职能，缺乏专业分工"], "consequences": ["产品落地难、获客难", "合规隐患累积", "业务增长天花板低"], "recommendations": ["建立每周固定学习计划，聚焦 1-2 个核心能力补强", "选择 1-2 个垂直领域 AI 工具深度使用，而非泛泛体验", "复杂决策（法律/财税/股权）借助专业顾问", "把非标服务逐步沉淀为标准化流程与产品"], "governance": {"immediate": ["梳理当前最痛的 1 个能力短板，列出可学习的课程或资料", "停止同时追新工具，确定 1-2 个核心 AI 工具"], "sevenDay": ["为核心 AI 工具建立使用 SOP（输入-复核-输出流程）", "预约一次法律/财税顾问咨询，解决最紧急的合规疑问"], "longTerm": ["将非标业务沉淀为标准产品/服务包，建立可复制交付流程", "加入行业社群，持续获取跨领域知识与人脉"]}, "externalSupport": ["行业导师 / 创业社群", "法律、财税专业顾问", "营销获客顾问"], "agentFollowup": ["在您的业务中，您最常用哪些 AI 工具？感觉哪些环节最吃力？", "过去半年，您是否参加过任何与创业相关的培训或社群？", "如果只能提升一项能力，您最希望提升什么？"]}, {"id": "1.2", "name": "生理与精力脆弱风险", "shortName": "生理精力", "categoryId": "internal", "categoryName": "内源主体脆弱性风险", "characterImage": "character_1_2.jpg", "characterImagePlaceholder": "😴", "color": "#5B8FF9", "level": "high", "description": "创业者个人健康出现单点故障或长期职业倦怠，工作生活边界模糊、缺乏支持，企业运营高度依赖个人身心状态。", "specificRisks": [{"id": "1.2.1", "name": "身体健康风险", "quote": "4月份我基本上身体躯体化，肩颈、头晕、心脏不舒服，持续了将近一个月。我之所以生病，就是因为身体负荷不了了，我忽略自己的身体去做事情", "source": "SoloNest 宁宁"}, {"id": "1.2.2", "name": "精力与心力耗竭", "quote": "干到后面不是体力不够，是能量没有了…长久的注意力，长久的脑力和体力和心力的持续的要求，这也是挑战，持续性是个很大的挑战。", "source": "SoloNest Karen"}, {"id": "1.2.3", "name": "角色冲突与孤立", "quote": "下班回家第一件事就是抱小孩、跟老婆聊聊天、跟家人聊聊天，这个时间可能就过去一个到一个半小时了…有时候老婆还在做家务，她会觉得你一回来就坐那儿不知道在搞什么。", "source": "SoloNest 王铁军"}], "symptoms": ["睡眠质量下降、长期疲劳", "身体出现肩颈、头晕、心脏不适等躯体化信号", "对工作丧失热情、能量感消失", "工作与家庭角色边界模糊，家人不理解"], "causes": ["长时间独自工作，缺乏人际支持", "工作生活边界模糊", "缺乏规律作息与运动", "忽略身体发出的预警信号"], "consequences": ["履约中断、交付延迟", "客户流失", "企业连续性受损"], "recommendations": ["建立强制休息机制（每日 7 小时睡眠、每周 1 天完全脱离工作）", "引入协作伙伴分担关键工作", "固定运动时间，建议每周 3 次以上", "定期体检，建立健康档案"], "governance": {"immediate": ["本周至少安排 1 天完全脱离工作休息", "今晚起固定就寝时间，保证 7 小时睡眠"], "sevenDay": ["安排一次体检或针对肩颈/睡眠问题的检查", "建立每周 3 次、每次 30 分钟的运动计划"], "longTerm": ["为关键任务建立备份机制，降低对个人状态的依赖", "与家人坦诚沟通角色分工，争取理解与支持"]}, "externalSupport": ["心理咨询师", "健康管理/体检机构", "外包协作伙伴"], "agentFollowup": ["您最近的睡眠质量如何？", "一天的工作中，您感觉最疲惫的是哪个时段？", "如果明天必须休假一天，您的工作能否正常进行？"]}, {"id": "1.3", "name": "认知与决策偏差风险", "shortName": "认知决策", "categoryId": "internal", "categoryName": "内源主体脆弱性风险", "characterImage": "character_1_3.jpg", "characterImagePlaceholder": "🔍", "color": "#5B8FF9", "level": "medium", "description": "在 AI 辅助决策过程中，过度自信、信息孤岛、沉没成本谬误等认知偏差，以及缺乏止损纪律的行为误区，导致决策质量下降。", "specificRisks": [{"id": "1.3.1", "name": "认知偏差陷阱", "quote": "发现很多人在走一个误区：觉得有了 AI 配合，就可以闷头造产品，造出来就觉得可以了。但其实造出产品只完成了 10%，剩下的还包括投资、市场推广、赛道是否足够长", "source": "SoloNest 王铁军"}, {"id": "1.3.2", "name": "行为决策误区", "quote": "你一定要给自己设一个止盈和那个止跌线的。别你们这头伸进去了，咔，几十万搭进去，搭完之后，然后什么都没有", "source": "SoloNest sevens"}], "symptoms": ["对 AI 生成结果不加验证直接采用", "与外界交流减少，决策视野收窄", "明知项目有问题仍持续投入", "缺乏止损/止盈纪律，越陷越深"], "causes": ["AI 辅助决策带来认知外包", "缺乏多元视角的反馈机制", "创业压力下过度相信自己的判断"], "consequences": ["资金损失", "机会成本上升", "方向性失误"], "recommendations": ["重要决策引入外部 review（朋友、导师或同行）", "为关键项目设置止损线与止盈线并严格执行", "建立决策 checklist，强制验证关键假设", "对 AI 输出保持「怀疑-验证」习惯"], "governance": {"immediate": ["给当前最重要的项目写下明确的止损线与止盈线", "把最近一次重大决策的依据写下来，找出 1 个未验证的假设"], "sevenDay": ["重大决策前强制征求 1 位外部人士的意见", "对 AI 给出的关键结论做一次交叉验证"], "longTerm": ["建立每月决策复盘机制，记录决策-结果-教训", "加入 1-2 个高质量的创业交流圈，保持多元视角"]}, "externalSupport": ["导师 / 同行评审", "行业分析师", "创业教练"], "agentFollowup": ["您最近一次重大决策，有没有征求过其他人的意见？", "您使用 AI 工具时，会不会对结果进行二次验证？", "如果项目连续 3 个月没有明显进展，您会如何选择？"]}, {"id": "1.4", "name": "资源禀赋边界风险", "shortName": "资源禀赋", "categoryId": "internal", "categoryName": "内源主体脆弱性风险", "characterImage": "character_1_4.jpg", "characterImagePlaceholder": "💰", "color": "#5B8FF9", "level": "high", "description": "企业资金储备有限、现金流单一、社会资本与人脉不足，且一人公司在获取政策与社会资源时面临隐性歧视，难以应对突发波动与规模化发展。", "specificRisks": [{"id": "1.4.1", "name": "资金储备与现金流风险", "quote": "第一是需要钱，前面完全靠自己正向现金流跑通会慢一点。第二是需要更多的合作支持。一人公司最难的就是只有一个人。", "source": "SoloNest Mango"}, {"id": "1.4.2", "name": "社会资本风险", "quote": "OPC 虽然社会比较关注，但是他事实上的发展还是被歧视的……不管是从公司法的规章制度上，还是从司法实践的层面上，对一人公司都是有歧视性的……所有的这些政策都是针对传统的科技公司。", "source": "鸿鹄汇 1"}], "symptoms": ["现金流紧张，依赖单一收入来源", "缺乏可调动的行业资源与人脉", "遭遇突发情况时无应对预案", "难以获得关键客户、合作机会或政策扶持"], "causes": ["收入结构单一、早期投入激进", "社交圈局限，影响合作机会", "对扶持政策与融资渠道了解不足", "一人公司面临制度性资源歧视"], "consequences": ["突发冲击无缓冲", "增长与融资受限", "关键机会流失"], "recommendations": ["建立 6 个月以上的现金储备", "主动构建客户与合作伙伴多元化矩阵", "定期参加行业活动扩展人脉", "关注并申请地方政府对小微/AI 创业的扶持资金"], "governance": {"immediate": ["盘点当前现金流可支撑月数，制定 3 个月收支预算", "梳理前 3 大客户收入占比，识别单一依赖风险"], "sevenDay": ["调研并申请 1-2 项适合的政府扶持/创业补贴", "参加 1 场行业活动，主动结识 5 位新联系人"], "longTerm": ["建立 6 个月现金储备目标与多元化客户结构", "构建稳定的行业人脉与合作伙伴网络"]}, "externalSupport": ["政府创业扶持政策咨询", "金融机构 / 小额信贷", "行业社群与孵化器"], "agentFollowup": ["您目前的现金储备可以支撑多久的运营？", "您的客户结构里，前 1 名客户占比是多少？", "您有没有尝试申请过政府或机构的扶持资金？"]}, {"id": "1.5", "name": "社会心理支持缺乏", "shortName": "社会支持", "categoryId": "internal", "categoryName": "内源主体脆弱性风险", "characterImage": "character_1_5.jpg", "characterImagePlaceholder": "🤝", "color": "#5B8FF9", "level": "medium", "description": "创业者的选择不被家人与社会理解，脱离组织后缺乏归属感与心理依托，长期孤立导致情绪耗竭与决策质量下降。", "specificRisks": [{"id": "1.5.1", "name": "社会认同缺失", "quote": "可能自己的父母或者是家人怎样的会觉得不理解。你明明可以上一个很好的班儿，你为什么不去呢？……他自己不被看见，自己也会觉得不开心。", "source": "SoloNest Lillian"}, {"id": "1.5.2", "name": "组织归属与身份认同", "quote": "以前都是属于在组织内的关系。现在可能在组织外，他肯定也是需要一个虚拟的这一东西去依托的", "source": "SoloNest sevens"}], "symptoms": ["家人朋友不理解创业选择", "缺乏可倾诉的创业伙伴", "脱离组织后身份认同感弱", "情绪低落、孤独感强"], "causes": ["社会对 OPC 认知不足", "脱离组织后缺乏社群连接", "一个人扛压力，缺乏支持网络"], "consequences": ["心理耗竭", "决策质量下降", "创业动力流失甚至退出"], "recommendations": ["加入创业者社群，建立同频支持网络", "定期与家人坦诚沟通，争取理解", "寻找 1-2 名可以深度交流的创业伙伴", "必要时寻求专业心理支持"], "governance": {"immediate": ["找到 1 个可以倾诉的伙伴，本周约一次深聊", "与家人开诚布公沟通一次创业选择与压力"], "sevenDay": ["加入 1 个创业者社群并参与线上/线下活动", "建立每周与同频伙伴固定交流的习惯"], "longTerm": ["构建稳定的支持网络与定期复盘机制", "明确自己的身份叙事：为什么创业、想成为什么样的人"]}, "externalSupport": ["创业者社群 / 行业协会", "心理咨询师", "行业活动与线下聚会"], "agentFollowup": ["家人朋友对您创业的态度如何？", "您有可以深度交流的创业伙伴吗？", "您如何评价自己目前的心理状态？"]}, {"id": "2.1", "name": "AI 协同双刃剑", "shortName": "AI 协同", "categoryId": "external", "categoryName": "外源环境与技术协同风险", "characterImage": "character_2_1.jpg", "characterImagePlaceholder": "🤖", "color": "#F6BD16", "level": "high", "description": "AI 输出存在幻觉与不稳定性，叠加「许愿式」使用方式，导致决策误导、代码崩溃等经营事故，AI 成为一把双刃剑。", "specificRisks": [{"id": "2.1.1", "name": "AI 技术可靠性风险", "quote": "国产的一些大模型，质谱或者 minimax 这些。它会有什么问题呢？就是它没有那么的精准，或者说会出现一些幻觉。这个就会导致他的代码期会有一些崩溃的现象", "source": "鸿鹄汇 2"}, {"id": "2.1.2", "name": "AI 使用方式风险", "quote": "我们把 AI 当成一个许愿池了——AI，你今天能不能帮我规划一下？明年我想挣 1000 万，你告诉我方案是什么？就是向 AI 去许愿了", "source": "OPC 许总"}], "symptoms": ["AI 输出不精准或出现幻觉", "关键业务环节高度依赖单一 AI 工具", "把 AI 当「许愿池」，直接要方案不拆解", "AI 输出导致交付事故或代码崩溃"], "causes": ["大模型幻觉难以完全消除", "缺乏 AI 输出复核机制", "对 AI 能力边界认知不足", "将大目标直接抛给 AI，缺少任务拆解"], "consequences": ["经营误判", "交付事故与客户信任受损", "关键流程崩溃"], "recommendations": ["关键决策保留人工最终审核环节", "对 AI 输出建立抽检与复核机制", "把大目标拆解为可执行步骤，再与 AI 协同", "关键代码、数据在本地验证后再投入使用"], "governance": {"immediate": ["对当前最关键的 AI 输出做一次人工复核", "把最近一次「许愿式」提问改写为带上下文与约束的提问"], "sevenDay": ["建立 AI 输出复核清单（事实、来源、逻辑、风险）", "为关键业务准备备用工具或人工兜底方案"], "longTerm": ["建立「AI 提议—人工审核—决策执行」的闭环机制", "定期评估 AI 工具效果，形成工具选型方法论"]}, "externalSupport": ["AI 技术顾问", "同行实践社群", "开发者社区"], "agentFollowup": ["您使用 AI 进行的关键决策，有没有人工最终把关？", "您是否遇到过 AI 给出的明显错误信息？", "您向 AI 提问时，会先拆解目标还是直接要方案？"]}, {"id": "2.2", "name": "平台与生态不确定", "shortName": "平台生态", "categoryId": "external", "categoryName": "外源环境与技术协同风险", "characterImage": "character_2_2.jpg", "characterImagePlaceholder": "🔗", "color": "#F6BD16", "level": "medium", "description": "业务高度依赖单一平台流量与规则，协作伙伴关系脆弱，外部政策与行业节奏错配，经营稳定性受外部环境影响大。", "specificRisks": [{"id": "2.2.1", "name": "平台依赖与规则风险", "quote": "我做 Temu 的时候，有一次突然收到了四百多条违规通知。当时我觉得店铺可能要被关掉了。货架电商最大的风险是平台哪天不给你流量了你就没流量了", "source": "SoloNest Mango"}, {"id": "2.2.2", "name": "协作网络脆弱性", "quote": "万一比方说 OPC 干着干着突然间跑路了，那钱还在我这里赚，我这边还会有个约束", "source": "OPC 许总"}, {"id": "2.2.3", "name": "外部环境不确定性", "quote": "智能硬件 OPC 扶持噱头大于实际，很多硬件创业公司根本拿不到真正的资源", "source": "SoloNest sevens"}, {"id": "2.2.4", "name": "行业错配", "quote": "在 AI 的这个时代背景下，不管是技术，还是商业模式，以及它整个公司发展的节奏。如果你按照传统的这种方式来的话，它是失灵的。它是没有效果的。", "source": "鸿鹄汇 1"}], "symptoms": ["收入高度依赖单一平台或客户", "突发违规、限流导致流量断崖", "外包/协作伙伴关系松散，缺乏约束", "沿用传统经营方式，与 AI 时代节奏错配"], "causes": ["平台规则多变、流量分配不透明", "缺乏备选渠道与多元化布局", "协作缺乏书面契约约束", "对行业趋势与政策变化跟踪不足"], "consequences": ["流量断崖、经营停摆", "交付中断", "关键合作机会流失"], "recommendations": ["建立多平台/多渠道经营矩阵，降低单一依赖", "与关键协作伙伴签署书面协议", "分散客户结构，避免单一客户占比过高", "跟踪行业趋势，用 AI 时代的节奏重构商业模式"], "governance": {"immediate": ["盘点单一平台/客户收入占比，确定 1 个备选渠道", "梳理关键协作伙伴名单，标记无契约约束的对象"], "sevenDay": ["与 1-2 名关键协作伙伴补签书面协议或合作备忘", "在备选渠道完成首次引流/获客测试"], "longTerm": ["建立多平台获客与多渠道交付体系", "每季度复盘行业趋势，调整商业模式节奏"]}, "externalSupport": ["平台运营顾问", "法律顾问（合作协议）", "行业情报与趋势研究"], "agentFollowup": ["您目前收入对单一平台或客户的依赖度有多高？", "您与关键外包或协作伙伴之间是否有书面协议？", "您平均多久关注一次所在行业的趋势变化？"]}, {"id": "2.3", "name": "法律与制度空白风险", "shortName": "法律制度", "categoryId": "external", "categoryName": "外源环境与技术协同风险", "characterImage": "character_2_3.jpg", "characterImagePlaceholder": "⚖️", "color": "#F6BD16", "level": "medium", "description": "一人公司承担更重的举证责任，面临制度空白与准入歧视，AIGC 知识产权归属与 AI 输出责任界定不明，合规风险高。", "specificRisks": [{"id": "2.3.1", "name": "主体形式与法人风险", "quote": "他如果注册是两人或者两人以上的有限责任公司，举证的话，其实就是对方举证，一人有限责任得自己举证", "source": "SoloNest Karen"}, {"id": "2.3.2", "name": "制度空白与准入歧视", "quote": "不管是我们说国央企的政府，还是公共事业单位的这些需求，它是很难释放给一人公司的。他连招投标的这个资格都进不去。", "source": "鸿鹄汇 1"}, {"id": "2.3.3", "name": "知识产权与内容合规", "quote": "我当时让他帮我把图案全部改掉，结果还是侵权了，你经常会在想象不到的地方违规", "source": "SoloNest Mango"}, {"id": "2.3.4", "name": "AI 输出责任归属", "quote": "万一 AI 输出的结果不是那么准确，出现责任的界定怎么办…谁签的订单谁负责", "source": "鸿鹄汇 2"}], "symptoms": ["一人公司需自证财产独立，举证责任重", "招投标、公共资源等准入资格受限", "AIGC 内容在想象不到的地方侵权", "AI 输出失误时责任归属不清"], "causes": ["一人公司制度设计特殊，财务不规范易失有限责任保护", "AIGC 版权与 AI 责任法律仍处灰色地带", "缺乏基础合规知识与审查流程"], "consequences": ["法律纠纷与赔偿责任", "商业机会流失", "公司主体风险穿透至个人"], "recommendations": ["规范财务与决策留痕，保持法人独立性", "AIGC 内容对外发布前做原创性核查", "关键内容（产品文案、品牌素材）保留人工再创作", "咨询专业律师完善合同、责任条款与主体结构"], "governance": {"immediate": ["检查近期对外发布的 AIGC 内容，排查侵权风险", "确认个人账户与公司账户是否完全隔离"], "sevenDay": ["建立内容版权核查与创作留痕机制", "梳理对外合同中的责任与赔偿条款"], "longTerm": ["咨询律师，完善主体形式、股权与责任隔离设计", "建立年度合规检查与法律顾问服务机制"]}, "externalSupport": ["律师（公司法 / 知识产权）", "财税顾问", "合规与内容审查服务"], "agentFollowup": ["您目前是否注册了经营主体？个人账户与公司账户是否隔离？", "您对外发布的 AI 生成内容，是否进行过原创性核查？", "您了解一人有限责任公司的举证责任要求吗？"]}]},
  initialQuestionnaire: {"meta": {"title": "OPC 风险预备问卷", "description": "问卷共 24 题，覆盖 2 大风险域、8 个风险类、24 项具体风险，用于初步识别个人/微型创业者在 AI 协同创业过程中的风险画像。", "scale": {"min": 1, "max": 5, "labels": {"1": "完全不同意", "2": "不同意", "3": "中立", "4": "同意", "5": "完全同意"}}, "version": "3.0"}, "author": "羽织梦", "motto": "以梦化羽；所织皆梦，所梦皆羽", "basicInfo": [{"id": "b1", "text": "您的经营主体形式是？", "options": ["未注册，个人经营", "个体工商户", "一人有限责任公司", "多人有限责任公司", "其他"]}, {"id": "b2", "text": "企业（或业务）已经运营多久？", "options": ["1 年以内", "1-3 年", "3-5 年", "5 年以上"]}, {"id": "b3", "text": "您目前的年营收规模约是？", "options": ["10 万以下", "10-50 万", "50-200 万", "200 万以上"]}, {"id": "b4", "text": "您平均每周工作多少小时？", "options": ["40 小时以内", "40-60 小时", "60-80 小时", "80 小时以上"]}, {"id": "b5", "text": "您对 AI 工具的依赖程度？", "options": ["偶尔使用", "经常使用", "核心环节依赖", "几乎全部依赖"]}, {"id": "b6", "text": "您是否有稳定的支持网络（合伙人、外包伙伴、社群、家人支持等）？", "options": ["完全没有", "较少", "有一些", "比较充足"]}], "categories": [{"id": "internal", "name": "内源主体脆弱性风险", "description": "源于创业者自身能力、健康、认知、资源与社会支持的风险", "color": "#5B8FF9"}, {"id": "external", "name": "外源环境与技术协同风险", "description": "源于 AI 技术、平台生态与制度环境的协同风险", "color": "#F6BD16"}], "questions": [{"id": "q1", "text": "我对 AI 技术本身的掌握还不够，担心能力跟不上业务需求", "categoryId": "internal", "riskId": "1.1", "riskName": "多维能力瓶颈风险", "specificRiskId": "1.1.1", "specificRiskName": "技术能力不足"}, {"id": "q2", "text": "我使用 AI 工具时经常沟通不畅、用不到点上，担心协同效率低", "categoryId": "internal", "riskId": "1.1", "riskName": "多维能力瓶颈风险", "specificRiskId": "1.1.2", "specificRiskName": "AI 协同能力滞后"}, {"id": "q3", "text": "我擅长做产品或服务，但不擅长推广获客与商业变现", "categoryId": "internal", "riskId": "1.1", "riskName": "多维能力瓶颈风险", "specificRiskId": "1.1.3", "specificRiskName": "管理与商业化能力缺失"}, {"id": "q4", "text": "我对法律、财税等专业知识了解不足，担心经营中踩坑", "categoryId": "internal", "riskId": "1.1", "riskName": "多维能力瓶颈风险", "specificRiskId": "1.1.4", "specificRiskName": "法律财税知识空白"}, {"id": "q5", "text": "我的业务高度依赖我个人，很难标准化复制，担心规模做不大", "categoryId": "internal", "riskId": "1.1", "riskName": "多维能力瓶颈风险", "specificRiskId": "1.1.5", "specificRiskName": "非标化规模壁垒"}, {"id": "q6", "text": "我长期高强度工作，身体已经出现疲劳、肩颈不适等预警信号", "categoryId": "internal", "riskId": "1.2", "riskName": "生理与精力脆弱风险", "specificRiskId": "1.2.1", "specificRiskName": "身体健康风险"}, {"id": "q7", "text": "我经常感到精力透支、心力不足，很难持续保持状态", "categoryId": "internal", "riskId": "1.2", "riskName": "生理与精力脆弱风险", "specificRiskId": "1.2.2", "specificRiskName": "精力与心力耗竭"}, {"id": "q8", "text": "我很难兼顾创业与家庭角色，家人对我的工作方式不太理解", "categoryId": "internal", "riskId": "1.2", "riskName": "生理与精力脆弱风险", "specificRiskId": "1.2.3", "specificRiskName": "角色冲突与孤立"}, {"id": "q9", "text": "我觉得把产品做出来就等于成功，容易忽视市场、推广等后续环节", "categoryId": "internal", "riskId": "1.3", "riskName": "认知与决策偏差风险", "specificRiskId": "1.3.1", "specificRiskName": "认知偏差陷阱"}, {"id": "q10", "text": "我在投入项目时缺乏止损/止盈纪律，容易越陷越深", "categoryId": "internal", "riskId": "1.3", "riskName": "认知与决策偏差风险", "specificRiskId": "1.3.2", "specificRiskName": "行为决策误区"}, {"id": "q11", "text": "我的现金储备有限，现金流压力大，难以应对突发经营波动", "categoryId": "internal", "riskId": "1.4", "riskName": "资源禀赋边界风险", "specificRiskId": "1.4.1", "specificRiskName": "资金储备与现金流风险"}, {"id": "q12", "text": "我的行业人脉与可调动资源有限，感受到对一人公司的不公平对待", "categoryId": "internal", "riskId": "1.4", "riskName": "资源禀赋边界风险", "specificRiskId": "1.4.2", "specificRiskName": "社会资本风险"}, {"id": "q13", "text": "家人或朋友不太理解我的创业选择，我经常感到不被看见", "categoryId": "internal", "riskId": "1.5", "riskName": "社会心理支持缺乏", "specificRiskId": "1.5.1", "specificRiskName": "社会认同缺失"}, {"id": "q14", "text": "离开组织后我缺乏归属感，缺少可以依托的社群或身份认同", "categoryId": "internal", "riskId": "1.5", "riskName": "社会心理支持缺乏", "specificRiskId": "1.5.2", "specificRiskName": "组织归属与身份认同"}, {"id": "q15", "text": "我使用的 AI 工具偶尔出现幻觉或不准确，我担心影响业务", "categoryId": "external", "riskId": "2.1", "riskName": "AI 协同双刃剑", "specificRiskId": "2.1.1", "specificRiskName": "AI 技术可靠性风险"}, {"id": "q16", "text": "我有时把 AI 当成「许愿池」直接要方案，缺少目标拆解与验证", "categoryId": "external", "riskId": "2.1", "riskName": "AI 协同双刃剑", "specificRiskId": "2.1.2", "specificRiskName": "AI 使用方式风险"}, {"id": "q17", "text": "我的业务高度依赖某个平台，担心平台限流或规则变化", "categoryId": "external", "riskId": "2.2", "riskName": "平台与生态不确定", "specificRiskId": "2.2.1", "specificRiskName": "平台依赖与规则风险"}, {"id": "q18", "text": "我的外包或协作伙伴关系松散，担心对方突然跑路影响交付", "categoryId": "external", "riskId": "2.2", "riskName": "平台与生态不确定", "specificRiskId": "2.2.2", "specificRiskName": "协作网络脆弱性"}, {"id": "q19", "text": "我能获得的政策扶持与外部资源有限，担心外部环境变化", "categoryId": "external", "riskId": "2.2", "riskName": "平台与生态不确定", "specificRiskId": "2.2.3", "specificRiskName": "外部环境不确定性"}, {"id": "q20", "text": "我沿用传统经营方式，感觉与 AI 时代的节奏不匹配", "categoryId": "external", "riskId": "2.2", "riskName": "平台与生态不确定", "specificRiskId": "2.2.4", "specificRiskName": "行业错配"}, {"id": "q21", "text": "我是一人经营或一人公司，担心财产、责任边界不清带来风险", "categoryId": "external", "riskId": "2.3", "riskName": "法律与制度空白风险", "specificRiskId": "2.3.1", "specificRiskName": "主体形式与法人风险"}, {"id": "q22", "text": "我难以获得招投标等公共资源准入资格，制度对一人公司并不友好", "categoryId": "external", "riskId": "2.3", "riskName": "法律与制度空白风险", "specificRiskId": "2.3.2", "specificRiskName": "制度空白与准入歧视"}, {"id": "q23", "text": "我担心 AI 生成内容侵权或不合规，影响对外发布与商业使用", "categoryId": "external", "riskId": "2.3", "riskName": "法律与制度空白风险", "specificRiskId": "2.3.3", "specificRiskName": "知识产权与内容合规"}, {"id": "q24", "text": "我担心 AI 输出失误时责任归属不清，最终要自己承担损失", "categoryId": "external", "riskId": "2.3", "riskName": "法律与制度空白风险", "specificRiskId": "2.3.4", "specificRiskName": "AI 输出责任归属"}]},
  knowledgeBase: {"version": "3.2", "lastUpdated": "2026-09-06", "author": "羽织梦", "motto": "以梦化羽；所织皆梦，所梦皆羽", "copyright": "© 2026 羽织梦 版权所有", "description": "智能体知识库 - 与《OPC企业风险故事线与风险链（完整版）》、《第五章 智能体设计》及质性调查《编码后的发现汇总》保持一致。​‌‌‌‌‌‌‌‌​‌‌‌‌​‌​‌‌‌‌‌‌​‌‌​​​‌‌‌​‌‌​‌​​​‌​‌​​‌‌​​​​​​​​​​‌‌‌‌‌​​​‌​​‌‌‌​‌‌‌​​‌​‌​‌‌​‌​​​‌​‌​​‌‌​​‌​‌​​‌‌​​​‌​‌‌​​‌‌‌‌‌‌‌‌​‌‌‌‌​‌‌‌‌‌‌‌‌‌​​​‌‌​‌‌​‌‌​​​‌​​‌​​​​​​​‌‌‌‌‌‌​‌‌​​​‌‌‌​‌‌‌​‌‌​‌​​​​‌‌​​‌‌​‌​​​‌​‌​​‌‌​‌‌‌‌‌‌‌‌​​​​‌‌​​​‌‌​​​‌​​‌​​​​​​​‌‌​‌​​​‌​‌​​‌‌​​‌‌‌​‌‌​‌​​​​‌‌​​‌‌‌‌‌‌‌‌​‌‌‌‌​‌", "faq": [{"id": "kb-001", "keywords": ["能力", "瓶颈", "学习", "AI 工具", "技能提升"], "question": "我担心自己能力不够，AI 也帮不上忙，怎么办？", "answer": "能力瓶颈的本质不是「学得不够多」，而是没有聚焦。建议：\n\n1. 只聚焦 1-2 个与业务直接相关的能力短板，每周固定时间深度学习\n2. 把 AI 当「协作者」而不是「老师」：先明确目标，再拆解步骤，让 AI 辅助每一步\n3. 复杂决策（法律、财税、股权）交给专业顾问，不必自己成为全才\n4. 把非标服务逐步沉淀为标准流程，降低对个人能力的依赖", "followup": ["您目前业务中最吃力的能力环节是什么？", "您每周能投入多少时间用于能力提升？"]}, {"id": "kb-002", "keywords": ["健康", "精力", "疲惫", "倦怠", "失眠", "压力"], "question": "创业压力大、身体和精力都跟不上了，怎么调整？", "answer": "对 OPC 来说，您本人就是公司最核心的资产，精力管理就是风险管理：\n\n1. 强制休息：每日 7 小时睡眠，每周至少 1 天完全脱离工作\n2. 固定运动：每周 3 次以上、每次 30 分钟，是性价比最高的精力投资\n3. 任务备份：把关键任务交给外包或协作伙伴，降低对个人状态的依赖\n4. 定期体检：身体发出的信号（肩颈、头晕、心慌）不要硬扛\n5. 情绪支持：与家人、同频创业者保持沟通，必要时求助心理咨询", "followup": ["您目前的作息和运动情况如何？", "您的工作中有哪些任务可以分担出去？"]}, {"id": "kb-003", "keywords": ["决策", "止损", "认知偏差", "沉没成本", "拍板"], "question": "怎么避免在项目上越陷越深、决策失误？", "answer": "认知偏差最难靠「更努力」克服，需要机制来兜底：\n\n1. 设止损线：投入前就写下「到什么程度就停止」，并严格执行\n2. 设止盈线：达到目标就兑现，不要总想「再等等」\n3. 外部视角：重大决策征求 1-2 位外部人士意见，打破信息孤岛\n4. 验证假设：对 AI 和自己的想法，先验证最关键的一个假设再做决定\n5. 定期复盘：每月回顾决策-结果-教训，形成自己的决策清单", "followup": ["您当前有没有正在纠结是否继续投入的项目？", "您最近一次重大决策的依据是什么？"]}, {"id": "kb-004", "keywords": ["资金", "现金流", "融资", "贷款", "补贴", "钱"], "question": "个人创业者的资金和现金流怎么管理？", "answer": "现金流是 OPC 的生命线，管理要点：\n\n1. 储备目标：保持 6 个月运营成本的现金储备\n2. 收入多元：前 1 名客户收入占比尽量不超过 30%\n3. 付款节奏：客户付款周期尽量短（30 天内），供应商付款周期尽量长\n4. 政策资金：主动申请创业担保贷款、科技型中小企业扶持等政策资金\n5. 融资顺序：先政府扶持、再小额信贷，最后才考虑股权融资", "followup": ["您目前的现金储备可以支撑几个月？", "您的客户结构是单一还是多元？"]}, {"id": "kb-005", "keywords": ["孤独", "支持", "社群", "家人", "认同", "心理"], "question": "一个人创业很孤独，家人朋友也不理解，怎么办？", "answer": "社会支持缺乏是 OPC 最常见的隐性风险，它影响的不只是情绪，还有决策质量：\n\n1. 找同频者：加入创业者社群，找到能深度交流的伙伴，每周固定交流\n2. 主动沟通：与家人坦诚分享创业的进展、压力和意义，争取理解\n3. 建立依托：用社群、导师或虚拟组织弥补脱离公司后的归属感\n4. 允许求助：持续情绪低落时，心理咨询是专业的支持资源\n5. 自我叙事：想清楚「为什么创业、想成为什么样的人」，这是内在支撑", "followup": ["您身边有没有可以深度交流的创业伙伴？", "家人对您创业的态度是怎样的？"]}, {"id": "kb-006", "keywords": ["AI 幻觉", "AI 可靠", "出错", "复核", "许愿池"], "question": "AI 输出不准、有幻觉，怎么放心使用？", "answer": "AI 不是许愿池，而是需要管理的工具：\n\n1. 先拆解再提问：把大目标拆成小任务，给 AI 明确的上下文和约束\n2. 人工复核：关键结论、代码、数据必须人工验证，建立复核清单\n3. 事实核查：涉及数字、法规、引用的内容，追查原始来源\n4. 关键业务兜底：为最核心的 AI 环节准备备用工具或人工方案\n5. 建立闭环：「AI 提议—人工审核—决策执行」，AI 永远不直接拍板", "followup": ["您使用 AI 时遇到过明显错误吗？", "您对 AI 输出的复核习惯是怎样的？"]}, {"id": "kb-007", "keywords": ["平台", "依赖", "限流", "封店", "流量", "渠道"], "question": "业务太依赖某个平台，怕被限流或封店，怎么办？", "answer": "平台依赖是结构性问题，需要提前布局：\n\n1. 多渠道矩阵：至少建立 2-3 个获客/交付渠道，分散单点风险\n2. 客户资产化：把平台流量沉淀到私域（社群、邮件、个人微信），掌握客户关系\n3. 规则预警：关注平台规则变化，合规经营，避免违规通知累积\n4. 书面协议：与关键协作伙伴签书面协议，防止对方跑路\n5. 节奏校准：跟踪行业趋势，用 AI 时代的模式重构业务，避免传统打法失灵", "followup": ["您目前收入对单一平台的依赖度有多高？", "您有没有开始布局平台之外的渠道？"]}, {"id": "kb-008", "keywords": ["一人公司", "法人", "举证", "有限责任", "主体"], "question": "一人公司的法律风险怎么防范？", "answer": "一人公司最大的风险是「财产混同」导致有限责任失效：\n\n1. 账户隔离：个人账户与公司账户严格分开，一切收支走对公\n2. 财务规范：建立规范账目，留存决策记录和票据，能证明财产独立\n3. 责任留痕：合同、交付、付款都留下书面证据，避免自证困难\n4. 主体设计：必要时引入第二股东或调整主体形式，优化责任结构\n5. 专业兜底：法律、财税问题咨询专业顾问，不要自己硬扛", "followup": ["您目前个人账户和公司账户是否完全隔离？", "您有规范的账目和决策留痕习惯吗？"]}, {"id": "kb-009", "keywords": ["AIGC", "版权", "侵权", "知识产权", "内容合规"], "question": "AI 生成内容会不会侵权？怎么合规使用？", "answer": "AIGC 版权仍是法律灰色地带，风险主要在「想象不到的地方违规」：\n\n1. 原创性核查：对外发布前检查 AI 内容与已有作品的相似度\n2. 人工再创作：关键内容（品牌素材、产品文案）在 AI 基础上人工修改，体现智力投入\n3. 来源留痕：保存创作过程记录，标注 AI 生成内容\n4. 授权检查：使用素材库、字体、图片时确认授权范围\n5. 台账管理：建立 AIGC 内容使用台账，便于追溯和举证", "followup": ["您对外发布的 AI 内容占比有多少？", "您目前有没有做内容原创性核查？"]}, {"id": "kb-010", "keywords": ["责任", "AI 失误", "订单", "赔偿", "风险归属"], "question": "AI 输出失误导致损失，责任算谁的？", "answer": "目前 AI 责任归属没有统一法律答案，但有一个基本原则：谁使用、谁负责、谁签单、谁承担。\n\n1. 明确边界：把 AI 定位为辅助工具，关键决策和交付由您把关\n2. 合同条款：在与客户的合同中明确 AI 介入环节与责任边界\n3. 内部留痕：保存 AI 输出、人工审核记录，证明尽到注意义务\n4. 风险预案：对高风险交付设置人工复核和保险/赔偿预案\n5. 专业咨询：涉及重大责任问题咨询专业律师", "followup": ["您的业务中 AI 参与哪些环节？", "您与客户的合同里是否提到 AI 相关内容？"]}, {"id": "kb-011", "keywords": ["OPC", "一人公司", "定义", "什么是"], "question": "什么是一人公司（OPC）？", "answer": "OPC（One Person Company，一人公司）指由单一自然人投资设立的有限责任公司，是介于个人独资企业和传统有限责任公司之间的企业形态。\n\n特点：\n- 投资人仅为 1 人，承担有限责任\n- 财务规范与举证责任要求更高（需自证财产独立）\n- 在 AI 时代，OPC 是兼顾灵活性与风险隔离的轻量化创业形态\n- 一人公司面临制度性偏见：招投标准入、融资、政策扶持往往不友好\n\n本 App 正是围绕 OPC 的 24 项特有风险提供筛查与治理建议。", "followup": ["您目前是个人经营还是已注册公司？", "您对一人公司的制度风险了解多少？"]}, {"id": "kb-012", "keywords": ["复盘", "复测", "评估", "怎么用", "功能", "帮助"], "question": "这个 App 能帮我做什么？", "answer": "我是您的 OPC 风险治理助手，覆盖「识别—评估—分级—预警—诊断—干预—复盘」全流程：\n\n1. 风险筛查：24 题问卷 + 基础信息，识别您的风险画像\n2. 风险分级：输出 0-100 风险分与「低风险/关注/预警/高风险」等级\n3. 深度诊断：AI 助手根据您的回答进一步追问，定位关键因素\n4. 治理建议：按「立即—7 日—中长期」生成可执行行动清单\n5. 动态复盘：每次复测与历史对比，跟踪风险变化\n\n建议先完成问卷，再与 AI 助手对话获取个性化诊断。", "followup": []}, {"id": "kb-013", "keywords": ["AI 依赖", "过度依赖", "能力退化", "认知依赖", "被 AI 裹挟"], "question": "用了 AI 之后会不会变得过度依赖，能力反而退化？", "answer": "会的，这是质性调查中最关键的提醒——AI 的「赋能」本身孕育着「依赖」的种子，效率的极致提升可能以能力的隐性退化为代价。\n\n典型表现：\n1. 判断力依赖：AI 越强、你越依赖，判断出现偏移时错误会被放大\n2. 认知外包：习惯让 AI 替你做决定，独立思考减少\n3. 能力闲置：长期不自己动手，技能生疏\n\n调查建议（来自受访创业者）：\n- 定期「无 AI 复盘」：关键决策先自己形成判断，再让 AI 补充视角\n- 要求 AI 给反向论证，主动对抗「迎合」\n- 明确哪些能力必须自己保留（思考方式、做事方法、客户关系）\n- 记住：AI 只能帮你加工，替代不了你的独特性", "followup": ["您目前哪些判断是直接采纳 AI 结果的？", "您有没有给自己设过「不依赖 AI 也能完成」的核心能力清单？"]}, {"id": "kb-014", "keywords": ["AI 谄媚", "迎合", "反向论证", "批判性使用", "多视角", "不同意见"], "question": "AI 总是顺着我说，怎么避免被它带偏？", "answer": "这是调查中多位受访者的共识：AI 本质上很「谄媚」——你动摇它支持你动摇，你笃定它给你加柴。所以必须自己把握主旋律。\n\n实践方法：\n1. 主动要求反方观点：「请给我 3 个反对理由」「换一个完全不同的视角」\n2. 模拟第三方评审：让 AI 扮演挑剔的评审、客户、律师来挑刺\n3. 多模型交叉验证：同一个问题问不同 AI，比较差异\n4. 建立「怀疑-验证」习惯：关键结论追原始来源\n5. 心力不足时可以让 AI 鼓励你，但重大决策不要只问一个 AI", "followup": ["您使用 AI 时会让它给出反方观点吗？", "您最近一次重要决策，AI 是顺着您还是提出了不同意见？"]}, {"id": "kb-015", "keywords": ["效率", "提效", "能力延展", "不会代码", "生产力", "十倍"], "question": "AI 到底能帮我提升多少效率？非技术背景也能做产品吗？", "answer": "调查显示 AI 对 OPC 的积极影响远超「省时间」，体现在三层：\n\n1. 效率跃升：有受访者报告整体工作提升 10-20 倍，不只是量的增长，而是时间分配重构——省下的时间投入更高价值的思考与决策\n2. 能力延展：非技术背景创业者借助 AI 做出了自己的小程序、工具网站（如「不用代码就可以建 App/网站」），跨越了原来的技能门槛\n3. 关系升维：从抗拒 AI → 工具化使用 → 伙伴式共创，人机关系逐步升级\n\n关键前提：效率优势建立在「你会拆解任务、审核结果」之上，否则幻觉会抵消效率红利。", "followup": ["您目前最想用 AI 突破的「不会做」的事情是什么？", "您现在的 AI 使用处于「工具」还是「伙伴」阶段？"]}, {"id": "kb-016", "keywords": ["放大螺旋", "小问题", "连锁", "内源", "外源", "为什么越来越糟"], "question": "为什么有些小问题会越滚越大，最后变成大危机？", "answer": "调查揭示了 OPC 特有的「脆弱性放大螺旋」：内源脆弱性越强，外源冲击的破坏力越大；外源冲击越剧烈，内源脆弱性越被加速暴露。三条链最容易出事：\n\n1. 认知偏差 → AI 误用 → 判断偏移：你越独断，AI 越顺着你，错误被放大\n2. 能力/资源短板 → 外部冲击承受力归零：没有资金缓冲和备选渠道，平台一次限流、伙伴一次跑路就可能击穿经营\n3. 社会心理缺位 → 决策孤岛：没人讨论、没有「第二双眼睛」，小问题拖成系统性危机\n\n反过来也有「生成性摩擦」：外部冲击（平台规则突变、行业调整）会倒逼 OPC 快速拼凑新方案——「船小好掉头」。关键是把被迫应对转化为主动创新。", "followup": ["您最近一次「差点出事」的经历，是哪条链被触发了？", "您现在有哪些「第二双眼睛」（外部视角）？"]}, {"id": "kb-017", "keywords": ["第二双眼睛", "决策孤岛", "孤独", "没人讨论", "外部视角"], "question": "一个人创业没有团队，决策时没人商量怎么办？", "answer": "调查显示 OPC 最大的隐性风险之一就是「决策孤岛」：面对 AI 幻觉、法律灰色地带等风险时，缺少第二双眼睛，心力被孤独消耗。\n\n破解方法（来自受访者实践）：\n1. 建立「虚拟董事会」：固定 2-3 位可深度交流的伙伴/导师，关键决策必问\n2. 用 AI 模拟不同角色（评审、客户、律师），弥补团队缺位——但记住 AI 会迎合，要它给反方\n3. 加入创业社群、行业联盟，形成网络化协作\n4. 对高风险的判断（法律、财务、重大承诺），坚持人工外部复核\n5. 把「找人说」制度化：每周固定一次复盘交流，而不是出了问题才找人", "followup": ["您目前有可以随时商量关键决策的人吗？", "如果为您的公司组一个「虚拟董事会」，您会请谁？"]}, {"id": "kb-018", "keywords": ["平台依附", "生态嵌入", "私域", "多渠道", "品牌资产", "网络化创业"], "question": "怎么从「靠平台给流量」变成自己的生意？", "answer": "调查给出的路径是：从「平台依附型创业」转向「生态嵌入型创业」。\n\n1. 私域沉淀：把平台流量导入社群、微信/邮件等自己可触达的渠道，掌握客户关系\n2. 多渠道获客：平台、内容、口碑、合作多条腿走路，单一渠道占比设上限\n3. 品牌资产沉淀：让客户认你的品牌和服务，而不是认平台推荐\n4. 协作网络：不同领域 OPC 围绕项目临时组队，实现技术、市场、资源互补，把「一人创业」升级为「网络化创业」\n5. 主动对接场景：争取平台企业、产业龙头、政府开放的应用需求，把创意变成商业价值", "followup": ["您的收入对单一平台的依赖占几成？", "您的客户有没有沉淀到自己的私域里？"]}, {"id": "kb-019", "keywords": ["超级个体", "复合能力", "技术有效市场无效", "重技术轻商业", "自我迭代"], "question": "怎样从「单一技能个体」成长为「复合能力超级个体」？", "answer": "OPC 一个人承担了研发、运营、营销、管理多重职能，最怕「重技术、轻商业」——技术有效但市场无效。\n\n调查给出的成长路径：\n1. 把技术优势转化为市场价值：先做需求识别和商业模式设计，用用户反馈、市场测试验证产品价值\n2. 补专业短板：财务、法律、组织管理基本意识在早期就建立，别等踩坑再学\n3. 从「机会驱动」转向「认知迭代」：定期复盘决策结果、用户反馈、资源配置，及时修正方向\n4. 建立自我迭代机制：AI 时代过去的经验会快速失效，唯一靠得住的是持续反思和学习能力", "followup": ["您现在的产品，客户真的愿意付费吗？验证过几次？", "您最需要补的一项能力是什么？"]}, {"id": "kb-020", "keywords": ["人机共智", "管理 AI", "任务设计", "多模型交叉验证", "人工决策"], "question": "怎么建立靠谱的「人机共智」工作模式？", "answer": "调查的核心结论：AI 的价值不取决于「会调用」，而取决于你会不会「管理 AI 完成任务」。\n\n可靠工作流：\n1. 从「向 AI 提问」升级为「管理 AI 完成任务」：明确目标 → 拆解流程 → 多轮验证 → 结果审核\n2. 多模型交叉验证：代码、内容、商业分析等重要输出，用不同 AI 交叉核对\n3. 人工审核兜底：AI 输出不直接进入商业流程，先过一遍审核\n4. 关键事项保留人工决策：涉及法律责任、客户承诺、战略判断的，AI 只能给参考，人拍板\n5. 建立复核清单：事实、来源、逻辑、风险四项逐条检查", "followup": ["您现在的 AI 工作流里有结果审核环节吗？", "哪些环节您会让 AI 直接进商业流程？"]}, {"id": "kb-021", "keywords": ["制度", "营商环境", "仲裁", "准入", "政策建议", "合规服务"], "question": "一人公司面临的制度障碍，现实中有哪些改善方向？", "answer": "调查把制度适配不足列为制约 OPC 发展的重要因素，改善方向包括：\n\n1. 合规服务下沉：标准合同模板、知识产权咨询、AI 内容合规指引，让 OPC 低成本获得专业支持\n2. 纠纷处理降成本：推动设立 AI 时代 OPC 专属商事仲裁通道，简化流程、降低费用\n3. 融资扶持：创业基金、专项扶持、低成本服务平台，缓解规模小、融资弱的问题\n4. 市场准入更包容：探索让有创新能力的 OPC 进入更多招投标、公共资源等商业场景\n\n对您个人而言，短期内能做的：主动使用标准化合规工具、保留完整证据链、加入行业协会获取政策信息、对涉及准入的订单提前咨询专业顾问。", "followup": ["您最近遇到过的制度性障碍是哪一类？", "您有没有用上所在地的创业扶持政策？"]}], "researchFindings": {"title": "《编码后的发现汇总》质性调查发现", "source": "调查资料：编码后的发现汇总.pdf（访谈编码分析）", "sample": "受访对象为 OPC（一人公司/AI 个人创业者）；「AI 协同双刃剑」选择性编码覆盖 11/18 位受访者", "topics": [{"id": "finding-1", "title": "AI 双刃剑的矛盾统一", "summary": "AI 对 OPC 同时产生积极与消极影响，二者相互依存、动态转化：赋能本身孕育依赖的种子，依赖加深又放大赋能的脆弱性。", "positive": ["效率跃升：受访者报告整体工作提升 10-20 倍，时间分配被重构，省下的时间投入更高价值思考与决策", "能力延展：非技术背景创业者借助 AI 做出小程序、工具网站，跨越技能门槛，具有结构性赋权意义", "关系升维：从抗拒、工具化使用发展为伙伴式共创，进入「人智共创」层面"], "negative": ["可靠性陷阱：AI 幻觉、上下文错误、代码崩溃；复杂合规场景输出不确定（如一夜 400 条违规通知）", "认知依赖侵蚀：AI 具有「谄媚/迎合」特性，会强化而非纠正使用者的既有倾向，动摇时被放大动摇", "知识产权与责任灰色地带：AIGC 侵权难以预料；「谁签单谁负责」，一人公司无组织层面缓冲"], "transformation": ["批判性使用：要求 AI 给反向论证、模拟第三方视角、多一步思考与反问，抵御依赖反噬", "关系适配：AI 存在「工具—伙伴」连续光谱，随业务形态与情境变化；心力不足时可让 AI 支持，重大决策仍需自主", "悖论循环：关系演进为「赋能—共创—共生」三层；须同时在「创始人单点体系」与「AI+外部生态体系」两条链路构建韧性"]}, {"id": "finding-2", "title": "内源脆弱性与外源不确定性的动态耦合（脆弱性放大螺旋）", "summary": "内源脆弱性越强，外源冲击破坏力越大；外源冲击越剧烈，内源脆弱性越被加速暴露。二者不是孤立叠加，而是互相放大的螺旋；但在一定条件下外源冲击也会倒逼内源进化（生成性摩擦）。", "chains": ["认知偏差→AI 误用→判断偏移链：创始人独断、信息孤岛（内源）遇上 AI 谄媚、不会反驳（外源），批判性思维越弱，AI 越从「增效工具」蜕变为「错误放大器」", "能力/资源短板→外部冲击承受力归零链：无组织冗余与资金缓冲（内源），平台规则突变、伙伴失信（外源）时一击即溃", "社会心理缺位→决策孤岛→风险识别失灵链：无团队讨论与情感支持，面对 AI 幻觉、法律灰色地带缺少「第二双眼睛」，小问题演变为系统性危机"], "generative": ["「船小好掉头」：平台规则突变、AI 工具迭代、政策调整会激活 OPC 的「拼凑行为」，用有限资源创造性地重组新方案", "案例：Mango 从 400 条违规的「濒死体验」中更懂平台规则并建立信心；Lucky 从版权投资转向 AI 经纪平台，外源合规限制倒逼产品重构", "外源风险的破坏性取决于创始人能否把「被迫应对」转化为「主动创新」"]}, {"id": "finding-3", "title": "OPC 创业韧性提升路径（从脆弱型单人成长转向韧性型智能创业）", "summary": "围绕「主体能力强化、人机协同优化、生态网络构建、制度环境完善」四个层面提升韧性。", "paths": ["打造自我迭代的「超级个体」：突破重技术轻商业，用用户反馈验证产品价值；补财务/法律/组织管理意识；建立持续反思与动态调整机制，从「机会驱动型创业」转向「认知迭代型创业」", "构建「人机共智」模式：从「向 AI 提问」升级为「管理 AI 完成任务」；代码/内容/分析采用多模型交叉验证、人工审核；法律责任、客户承诺、战略判断保留人工决策", "构建生态化支撑体系：降低单一平台依赖（私域运营、多渠道获客、品牌资产沉淀）；通过创业社区、行业联盟建立协作网络，将「一人创业」升级为「网络化创业」；推动平台、龙头、政府开放应用场景", "完善制度保障环境：提供标准化合同模板、知识产权咨询、AI 内容合规指引与专属商事仲裁通道；以创业基金、专项扶持、低成本服务平台优化营商环境，探索包容的市场准入机制"]}]}, "greetings": ["您好，我是您的 OPC 风险治理助手，已完成您问卷的初步分析。接下来我会针对您最突出的风险，与您深入聊一聊。", "欢迎来到深度访谈环节！我会根据您的问卷结果，帮您把最需要关注的风险问清楚、理明白。", "您好！我已经读了您的风险画像，接下来我们一条一条地确认，请放轻松回答就好。"], "closingResponses": {"thanks": "不客气！治理风险的关键是行动，建议从「立即处理事项」开始。", "ok": "好的，我已记录您的回答，会结合它完善您的风险判断。", "bye": "再见！您可以在报告页随时查看完整画像和治理清单。"}, "_mark": "羽织梦|以梦化羽；所织皆梦，所梦皆羽"}
};
